240	  constructor(private readonly app: App) {
241	    // Color は内部でリニアに直されるので、シェーダーに渡す sRGB の値を取り直す。
242	    BACKDROP.getRGB(_clearColor, THREE.SRGBColorSpace);
243	    this.compositeMaterial.uniforms.backdrop.value.set(_clearColor.r, _clearColor.g, _clearColor.b);
244	    const quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), this.compositeMaterial);
245	    quad.frustumCulled = false;
246	    this.compositeScene.add(quad);
247	
248	    // 枠は手に重なる位置にあるので、深度を無視して常に見せる。
249	    const barMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff, depthTest: false, side: THREE.DoubleSide });
250	    const barGeometry = new THREE.PlaneGeometry(1, 1);
251	    for (let i = 0; i < 4; i++) {
252	      const bar = new THREE.Mesh(barGeometry, barMaterial);
253	      bar.renderOrder = 90;
254	      this.bars.push(bar);
255	      this.frame.add(bar);
256	    }
257	    this.flash = new THREE.Mesh(
258	      barGeometry,
259	      new THREE.MeshBasicMaterial({
260	        color: 0xffffff,
261	        transparent: true,
262	        opacity: 0,
263	        depthTest: false,
264	        side: THREE.DoubleSide,
265	      }),
266	    );
267	    this.flash.renderOrder = 89;
268	    this.flash.visible = false;
269	    this.frame.add(this.flash);
270	    this.frame.visible = false;
271	    app.scene.add(this.frame);
272	
273	    app.menu.addToggle(
274	      '手で撮影',
275	      () => this.enabled,
276	      (value) => (this.enabled = value),
277	    );
278	    // 枠を作っている間は、親指の動きがつまみと判定されても道具を発動させない。
279	    app.tools.addInterceptor(() => this.active);
280	    app.onClear(() => this.clearWorldPhotos());
281	  }
