294	  /**
295	   * カメラの映像を取り始める。許可のダイアログが出るので、MR を始める前に、
296	   * ユーザー操作 (ボタンのクリック) の中で呼ぶ。
297	   * deviceId を省くと、背面 (パススルー) のカメラらしいものを選ぶ。
298	   */
299	  async startCamera(deviceId?: string): Promise<CameraInfo | null> {
300	    const media = navigator.mediaDevices;
301	    if (!media?.getUserMedia) return null;
302	    const size = { width: { ideal: 1280 }, height: { ideal: 960 } };
303	    this.stopCamera();
304	    let stream = await media.getUserMedia({
305	      video: deviceId ? { deviceId: { exact: deviceId }, ...size } : { facingMode: 'environment', ...size },
306	    });
307	    // カメラの名前は、許可が下りたあとでないと読めない。
308	    const cameras = (await media.enumerateDevices())
309	      .filter((device) => device.kind === 'videoinput')
310	      .map((device, i) => ({ deviceId: device.deviceId, label: device.label || `カメラ ${i + 1}` }));
311	    let current = stream.getVideoTracks()[0]?.getSettings().deviceId ?? '';
312	    if (!deviceId) {
313	      // Quest のブラウザには、アバターを映す仮想カメラもある。facingMode の指定が効かずに
314	      // そちらが選ばれた場合に備えて、名前からも背面のカメラを探す。
315	      // Quest 3 では "camera 1, facing back" と "camera 2, facing back" の 2 つがあり、
316	      // 画角と傾きの値は camera 2 で合わせてあるので、そちらを優先する。
317	      const back =
318	        cameras.find((camera) => /camera 2\b.*back/i.test(camera.label)) ??
319	        cameras.find((camera) => /back|rear|environment|passthrough/i.test(camera.label));
320	      if (back && back.deviceId !== current) {
321	        for (const track of stream.getTracks()) track.stop();
322	        stream = await media.getUserMedia({ video: { deviceId: { exact: back.deviceId }, ...size } });
323	        current = back.deviceId;
324	      }
325	    }
326	
327	    const video = document.createElement('video');
328	    video.srcObject = stream;
329	    video.muted = true;
330	    video.playsInline = true;
331	    await video.play();
332	    const texture = new THREE.VideoTexture(video);
333	    // 色の変換は合成のシェーダーで自前で行うので、映像の値をそのまま読む。
334	    texture.colorSpace = THREE.NoColorSpace;
335	    this.video = video;
336	    this.videoTexture = texture;
337	    this.compositeMaterial.uniforms.videoMap.value = texture;
338	    return { video, cameras, deviceId: current };
339	  }
340	
341	  private stopCamera(): void {
342	    const stream = this.video?.srcObject as MediaStream | null | undefined;
343	    for (const track of stream?.getTracks() ?? []) track.stop();
344	    this.video?.remove();
345	    this.videoTexture?.dispose();
346	    this.video = null;
347	    this.videoTexture = null;
348	    this.compositeMaterial.uniforms.videoMap.value = null;
349	  }
