449	  /** 両手が枠の形になっているか。すでに枠が出ているときは、条件をゆるめて保つ。 */
450	  private checkShape(head: THREE.Vector3): boolean {
451	    const { left, right } = this;
452	    _diagonal.subVectors(right.corner, left.corner);
453	    const distance = _diagonal.length();
454	    if (distance < MIN_SIDE || distance > MAX_SIDE * 1.5) return false;
455	    // 手が頭に近すぎる / 遠すぎるときは、枠として扱わない。
456	    const reach = _c.addVectors(left.corner, right.corner).multiplyScalar(0.5).distanceTo(head);
457	    if (reach < 0.1 || reach > 1) return false;
458	
459	    _diagonal.divideScalar(distance);
460	    const view = _normal.copy(_c).sub(head).normalize();
461	    const leftAcross = Math.abs(left.indexDirection.dot(view));
462	    const rightAcross = Math.abs(right.indexDirection.dot(view));
463	    const indexOpposed = left.indexDirection.dot(right.indexDirection);
464	
465	    if (this.active) {
466	      // 撮るために親指を倒している間も枠を保つので、親指の形は見ない。ただし両方倒したら枠をやめる。
467	      // 人差し指が前を指す、曲がる、同じ向きに揃う、のどれかで枠は消える。
468	      return (
469	        left.indexStraightness > INDEX_STRAIGHT_HOLD &&
470	        right.indexStraightness > INDEX_STRAIGHT_HOLD &&
471	        leftAcross < ACROSS_VIEW_HOLD &&
472	        rightAcross < ACROSS_VIEW_HOLD &&
473	        indexOpposed < OPPOSED_HOLD &&
474	        left.indexDirection.dot(_diagonal) > 0 &&
475	        right.indexDirection.dot(_diagonal) < 0 &&
476	        !(left.folded && right.folded)
477	      );
478	    }
479	    if (left.indexStraightness < INDEX_STRAIGHT_FORM || right.indexStraightness < INDEX_STRAIGHT_FORM) return false;
480	    if (left.folded || right.folded || left.thumbGap < THUMB_OPEN || right.thumbGap < THUMB_OPEN) return false;
481	    // 指が視線に対して横に寝ていること。レイで何かを指している手は、ここで外れる。
482	    if (leftAcross > ACROSS_VIEW_FORM || rightAcross > ACROSS_VIEW_FORM) return false;
483	    if (Math.abs(left.thumbDirection.dot(view)) > ACROSS_VIEW_HOLD) return false;
484	    if (Math.abs(right.thumbDirection.dot(view)) > ACROSS_VIEW_HOLD) return false;
485	    // 両手の L 字が、互い違いに向かい合っていること。人差し指どうし、親指どうしが逆を向き、
486	    // それぞれの指が相手の手の角へ向かう成分を持つ。両手をただ広げて並べた形は、ここで外れる。
487	    if (indexOpposed > OPPOSED_FORM) return false;
488	    if (left.thumbDirection.dot(right.thumbDirection) > OPPOSED_HOLD) return false;
489	    if (left.indexDirection.dot(_diagonal) < INWARD_MIN || left.thumbDirection.dot(_diagonal) < INWARD_MIN) return false;
490	    if (right.indexDirection.dot(_diagonal) > -INWARD_MIN || right.thumbDirection.dot(_diagonal) > -INWARD_MIN) {
491	      return false;
492	    }
493	    return true;
494	  }
495	
496	  /** 両手の角を対角とする四角形を、頭のほうを向く平面の上に作る。 */
497	  private updateRect(head: THREE.Vector3, headQuaternion: THREE.Quaternion): void {
498	    this.center.addVectors(this.left.corner, this.right.corner).multiplyScalar(0.5);
499	    _normal.subVectors(head, this.center).normalize();
500	    // 写真が傾かないよう、上辺は水平にする。真上や真下を向いているときだけ、頭の向きに合わせる。
501	    if (Math.abs(_normal.y) < 0.95) _up.set(0, 1, 0);
502	    else _up.set(0, 1, 0).applyQuaternion(headQuaternion);
503	    _up.addScaledVector(_normal, -_up.dot(_normal)).normalize();
504	    _right.crossVectors(_up, _normal);
505	    this.quaternion.setFromRotationMatrix(_matrix.makeBasis(_right, _up, _normal));
506	    _diagonal.subVectors(this.right.corner, this.left.corner);
507	    this.width = THREE.MathUtils.clamp(Math.abs(_diagonal.dot(_right)) - FINGER_INSET * 2, MIN_SIDE, MAX_SIDE);
508	    this.height = THREE.MathUtils.clamp(Math.abs(_diagonal.dot(_up)) - FINGER_INSET * 2, MIN_SIDE, MAX_SIDE);
509	  }
510	
511	  private updateFrame(time: number): void {
512	    const flashing = time < this.flashUntil;
513	    this.frame.visible = this.active || flashing;
514	    if (!this.frame.visible) return;
515	    const { width, height } = this;
516	    this.frame.position.copy(this.center);
517	    this.frame.quaternion.copy(this.quaternion);
518	    const [top, bottom, left, right] = this.bars;
519	    top.position.set(0, height / 2, 0);
520	    bottom.position.set(0, -height / 2, 0);
521	    top.scale.set(width + BORDER, BORDER, 1);
522	    bottom.scale.copy(top.scale);
523	    left.position.set(-width / 2, 0, 0);
524	    right.position.set(width / 2, 0, 0);
525	    left.scale.set(BORDER, height + BORDER, 1);
526	    right.scale.copy(left.scale);
527	    this.flash.visible = flashing;
528	    this.flash.scale.set(width, height, 1);
529	    this.flash.material.opacity = flashing ? (0.7 * (this.flashUntil - time)) / FLASH_DURATION : 0;
530	  }
