1	import * as THREE from 'three';
2	import type { App, Feature, FrameContext } from '../app';
3	import type { HandState } from '../input';
4	import { RAPIER } from '../physics';
5	
6	export type ToyKind = 'ball' | 'block';
7	type GrabButton = 'select' | 'squeeze';
8	
9	interface Toy {
10	  kind: ToyKind;
11	  mesh: THREE.Mesh<THREE.BufferGeometry, THREE.MeshStandardMaterial>;
12	  body: RAPIER.RigidBody;
13	  collider: RAPIER.Collider;
14	  /** 拡大率。両手でつかんで変える。 */
15	  scale: number;
16	  holders: HandState[];
17	  /** 片手で持っているときの、手から見た物の位置と向き */
18	  offsetPosition: THREE.Vector3;
19	  offsetQuaternion: THREE.Quaternion;
20	  /** 両手で持ち始めた瞬間の状態 */
21	  twoHand: {
22	    middle: THREE.Vector3;
23	    direction: THREE.Vector3;
24	    distance: number;
25	    scale: number;
26	    relativePosition: THREE.Vector3;
27	    quaternion: THREE.Quaternion;
28	  } | null;
29	  lastImpactTime: number;
30	}
31	
32	/** 球の半径 / ブロックの一辺の半分 (m) */
33	const BASE_SIZE = 0.05;
34	const MIN_SCALE = 0.4;
35	const MAX_SCALE = 6;
36	const MAX_TOYS = 40;
37	/** 物の表面からこの距離までなら、つかめる (m) */
38	const GRAB_MARGIN = 0.05;
39	/** これより遅い衝突では音を出さない (m/s) */
40	const MIN_IMPACT_SPEED = 0.3;
41	const MIN_IMPACT_INTERVAL = 0.08;
42	
43	const BALL_GEOMETRY = new THREE.SphereGeometry(BASE_SIZE, 32, 20);
44	const BLOCK_GEOMETRY = new THREE.BoxGeometry(BASE_SIZE * 2, BASE_SIZE * 2, BASE_SIZE * 2);
45	
46	const _a = new THREE.Vector3();
47	const _b = new THREE.Vector3();
48	const _delta = new THREE.Quaternion();
49	
50	/**
51	 * つかんで投げられるボールとブロック。現実の床・壁・机 (Room の当たり判定) で跳ね返る。
52	 * - 物の近くでつまむ / グリップを握る: つかむ
53	 * - 何もない所でつまむ / トリガー: 手の中に新しく出す
54	 * - 両手で同じ物をつかむ: 手の間隔で拡大縮小、手の向きで回転
55	 */
56	export class Toys implements Feature {
57	  readonly name = 'toys';
58	  /** 物がぶつかったときの通知 (効果音用) */
59	  onImpact: ((position: THREE.Vector3, speed: number, kind: ToyKind) => void) | null = null;
60	
61	  private readonly toys: Toy[] = [];
62	  private readonly byCollider = new Map<number, Toy>();
63	  private readonly held = new Map<HandState, { toy: Toy; button: GrabButton }>();
64	  private time = 0;
65	
66	  constructor(private readonly app: App) {
67	    const { input, tools } = app;
68	    tools.addInterceptor((hand) => this.tryGrab(hand, 'select'));
69	    input.on('selectend', (hand) => this.release(hand, 'select'));
70	    input.on('squeezestart', (hand) => void this.tryGrab(hand, 'squeeze'));
71	    input.on('squeezeend', (hand) => this.release(hand, 'squeeze'));
72	
73	    tools.register({
74	      id: 'ball',
75	      label: 'ボール',
76	      hint: 'つまむ/トリガーで出し、離して投げる',
77	      onSelectStart: (hand) => this.spawnInHand('ball', hand),
78	    });
79	    tools.register({
80	      id: 'block',
81	      label: 'ブロック',
82	      hint: '出して積む。両手でつかむと拡大・回転',
83	      onSelectStart: (hand) => this.spawnInHand('block', hand),
84	    });
85	    app.onClear(() => this.clear());
86	    app.physics.onCollisionStart((c1, c2) => this.handleCollision(c1, c2));
87	  }
88	
89	  get count(): number {
90	    return this.toys.length;
91	  }
92	
93	  end(): void {
94	    this.clear();
95	  }
96	
97	  clear(): void {
98	    while (this.toys.length > 0) this.remove(this.toys[0]);
99	  }
100	
101	  update(ctx: FrameContext): void {
102	    this.time = ctx.time;
103	    for (let i = this.toys.length - 1; i >= 0; i--) {
