30	export class App {
31	  // stencil はポータル (壁の穴) の描画で使う。XR のフレームバッファにも引き継がれる。
32	  readonly renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, stencil: true });
33	  readonly scene = new THREE.Scene();
34	  readonly camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.05, 100);
35	  readonly input = new Input();
36	  readonly tools = new Tools(this.input);
37	  readonly menu = new Menu(this);
38	  readonly physics = new Physics();
39	  session: XRSession | null = null;
40	  onSessionStart: ((session: XRSession) => void) | null = null;
41	  onSessionEnd: (() => void) | null = null;
42	
43	  private readonly features: Feature[] = [];
44	  private readonly failed = new Set<Feature>();
45	  private readonly clearHandlers: (() => void)[] = [];
46	  private readonly headPosition = new THREE.Vector3();
47	  private readonly headQuaternion = new THREE.Quaternion();
48	  private lastTime = 0;
49	
50	  constructor() {
51	    this.renderer.setPixelRatio(window.devicePixelRatio);
52	    this.renderer.setSize(window.innerWidth, window.innerHeight);
53	    this.renderer.xr.enabled = true;
54	    this.renderer.xr.setReferenceSpaceType('local-floor');
55	    document.body.appendChild(this.renderer.domElement);
56	    this.add(this.input);
57	    this.add(this.menu);
58	    window.addEventListener('resize', () => {
59	      if (this.renderer.xr.isPresenting) return;
60	      this.camera.aspect = window.innerWidth / window.innerHeight;
61	      this.camera.updateProjectionMatrix();
62	      this.renderer.setSize(window.innerWidth, window.innerHeight);
63	    });
64	  }
65	
66	  add<T extends Feature>(feature: T): T {
67	    this.features.push(feature);
68	    return feature;
69	  }
70	
71	  /** メニューの「全部消す」で呼ばれる処理を登録する。 */
72	  onClear(handler: () => void): void {
73	    this.clearHandlers.push(handler);
74	  }
75	
76	  clearAll(): void {
77	    for (const handler of this.clearHandlers) handler();
78	  }
79	
80	  async enterXR(): Promise<void> {
81	    if (this.session || !navigator.xr) return;
82	    // immersive-ar はパススルー映像の上に描画するセッション。
83	    // optionalFeatures は非対応でもセッション開始に失敗せず、session.enabledFeatures で結果が分かる。
84	    const session = await navigator.xr.requestSession('immersive-ar', {
85	      requiredFeatures: REQUIRED_FEATURES.map((f) => f.id),
86	      optionalFeatures: OPTIONAL_FEATURES.map((f) => f.id),
87	      // GPU テクスチャとして深度を受け取る (three.js が遮蔽に使う)。形式はブラウザ任せ。
88	      depthSensing: { usagePreference: ['gpu-optimized'], dataFormatPreference: [] },
89	    });
90	    await this.renderer.xr.setSession(session);
91	    this.session = session;
92	    this.lastTime = 0;
93	    this.failed.clear();
94	    session.addEventListener('end', this.handleSessionEnd);
95	    this.onSessionStart?.(session);
96	
97	    for (const feature of this.features) {
98	      try {
99	        await feature.start?.(session);
100	      } catch (error) {
101	        this.reportFailure(feature, 'start', error);
102	      }
103	    }
104	    this.renderer.setAnimationLoop(this.handleFrame);
105	  }
106	
107	  private readonly handleSessionEnd = (): void => {
108	    this.renderer.setAnimationLoop(null);
109	    for (const feature of this.features) {
110	      try {
111	        feature.end?.();
112	      } catch (error) {
113	        this.reportFailure(feature, 'end', error);
114	      }
115	    }
116	    this.session = null;
117	    this.onSessionEnd?.();
118	  };
119	
120	  private readonly handleFrame = (timeMs: number, frame?: XRFrame): void => {
121	    const session = this.session;
122	    const refSpace = this.renderer.xr.getReferenceSpace();
123	    if (!frame || !session || !refSpace) return;
124	
125	    const time = timeMs / 1000;
126	    const dt = this.lastTime === 0 ? 1 / 72 : Math.min(time - this.lastTime, 0.05);
127	    this.lastTime = time;
128	
129	    const viewerPose = frame.getViewerPose(refSpace);
130	    if (viewerPose) {
131	      const { position, orientation } = viewerPose.transform;
132	      this.headPosition.set(position.x, position.y, position.z);
133	      this.headQuaternion.set(orientation.x, orientation.y, orientation.z, orientation.w);
134	    }
135	
136	    const ctx: FrameContext = {
137	      time,
138	      dt,
139	      frame,
140	      session,
141	      refSpace,
142	      headPosition: this.headPosition,
143	      headQuaternion: this.headQuaternion,
144	    };
145	    for (const feature of this.features) {
146	      if (this.failed.has(feature)) continue;
147	      try {
148	        feature.update?.(ctx);
149	      } catch (error) {
150	        this.reportFailure(feature, 'update', error);
151	      }
152	    }
153	    this.renderer.render(this.scene, this.camera);
154	  };
155	
156	  /** 失敗した機能は以後の update を止める。毎フレーム同じ例外を投げ続けないため。 */
157	  private reportFailure(feature: Feature, phase: string, error: unknown): void {
158	    this.failed.add(feature);
159	    console.error(`[${feature.name}] ${phase} に失敗したため、この機能を停止します`, error);
160	  }
161	}
