67	
68	  private begin(hand: HandState): void {
69	    if (!hand.tracked) return;
70	    const color = COLORS[this.nextColor];
71	    this.nextColor = (this.nextColor + 1) % COLORS.length;
72	    this.active.set(hand, this.createStroke(penPosition(hand), color));
73	  }
74	
75	  private finish(hand: HandState): void {
76	    const stroke = this.active.get(hand);
77	    this.active.delete(hand);
78	    // 動かさずに離した場合は、線にならないので捨てる。
79	    if (stroke && stroke.points.length < 2) {
80	      this.dispose(stroke);
81	      this.strokes.splice(this.strokes.indexOf(stroke), 1);
82	    }
83	  }
84	
85	  private createStroke(start: THREE.Vector3, color: number): Stroke {
86	    const material = new THREE.MeshStandardMaterial({
87	      color,
88	      emissive: color,
89	      emissiveIntensity: 0.35,
90	      roughness: 0.5,
91	    });
92	    const mesh = new THREE.Mesh(new THREE.BufferGeometry(), material);
93	    mesh.castShadow = true;
94	    // 線は長く伸びるので、作り直すたびに境界を計算するより、常に描画対象にする。
95	    mesh.frustumCulled = false;
96	    this.app.scene.add(mesh);
97	    const stroke: Stroke = { points: [start.clone()], mesh };
98	    this.strokes.push(stroke);
99	    return stroke;
100	  }
101	
102	  private dispose(stroke: Stroke): void {
103	    this.app.scene.remove(stroke.mesh);
104	    stroke.mesh.geometry.dispose();
105	    stroke.mesh.material.dispose();
106	  }
107	}
108	
109	function penPosition(hand: HandState): THREE.Vector3 {
110	  return hand.isHand ? hand.grabPosition : hand.tipPosition;
111	}
112	
113	/** 点列をなめらかな曲線でつなぎ、チューブ状のメッシュにする。 */
114	function rebuild(stroke: Stroke): void {
115	  stroke.mesh.geometry.dispose();
116	  stroke.mesh.geometry = new THREE.TubeGeometry(
117	    new THREE.CatmullRomCurve3(stroke.points),
118	    stroke.points.length * 2,
119	    RADIUS,
120	    6,
121	    false,
122	  );
123	}
