1	import * as THREE from 'three';
2	import type { App, Feature, FrameContext } from '../app';
3	import type { HandState } from '../input';
4	import { RAPIER } from '../physics';
5	
6	export type ToyKind = 'ball' | 'block';
7	type GrabButton = 'select' | 'squeeze';
8	
9	interface Toy {
10	  kind: ToyKind;
11	  mesh: THREE.Mesh<THREE.BufferGeometry, THREE.MeshStandardMaterial>;
12	  body: RAPIER.RigidBody;
13	  collider: RAPIER.Collider;
14	  /** 拡大率。両手でつかんで変える。 */
15	  scale: number;
16	  holders: HandState[];
17	  /** 片手で持っているときの、手から見た物の位置と向き */
18	  offsetPosition: THREE.Vector3;
19	  offsetQuaternion: THREE.Quaternion;
20	  /** 両手で持ち始めた瞬間の状態 */
21	  twoHand: {
22	    middle: THREE.Vector3;
23	    direction: THREE.Vector3;
24	    distance: number;
25	    scale: number;
26	    relativePosition: THREE.Vector3;
27	    quaternion: THREE.Quaternion;
28	  } | null;
29	  lastImpactTime: number;
30	}
31	
32	/** 球の半径 / ブロックの一辺の半分 (m) */
33	const BASE_SIZE = 0.05;
34	const MIN_SCALE = 0.4;
35	const MAX_SCALE = 6;
36	const MAX_TOYS = 40;
37	/** 物の表面からこの距離までなら、つかめる (m) */
38	const GRAB_MARGIN = 0.05;
39	/** これより遅い衝突では音を出さない (m/s) */
40	const MIN_IMPACT_SPEED = 0.3;
41	const MIN_IMPACT_INTERVAL = 0.08;
42	
43	const BALL_GEOMETRY = new THREE.SphereGeometry(BASE_SIZE, 32, 20);
44	const BLOCK_GEOMETRY = new THREE.BoxGeometry(BASE_SIZE * 2, BASE_SIZE * 2, BASE_SIZE * 2);
45	
46	const _a = new THREE.Vector3();
47	const _b = new THREE.Vector3();
48	const _delta = new THREE.Quaternion();
49	
50	/**
51	 * つかんで投げられるボールとブロック。現実の床・壁・机 (Room の当たり判定) で跳ね返る。
52	 * - 物の近くでつまむ / グリップを握る: つかむ
53	 * - 何もない所でつまむ / トリガー: 手の中に新しく出す
54	 * - 両手で同じ物をつかむ: 手の間隔で拡大縮小、手の向きで回転
55	 */
56	export class Toys implements Feature {
57	  readonly name = 'toys';
58	  /** 物がぶつかったときの通知 (効果音用) */
59	  onImpact: ((position: THREE.Vector3, speed: number, kind: ToyKind) => void) | null = null;
60	
61	  private readonly toys: Toy[] = [];
62	  private readonly byCollider = new Map<number, Toy>();
63	  private readonly held = new Map<HandState, { toy: Toy; button: GrabButton }>();
64	  private time = 0;
65	
66	  constructor(private readonly app: App) {
67	    const { input, tools } = app;
68	    tools.addInterceptor((hand) => this.tryGrab(hand, 'select'));
69	    input.on('selectend', (hand) => this.release(hand, 'select'));
70	    input.on('squeezestart', (hand) => void this.tryGrab(hand, 'squeeze'));
71	    input.on('squeezeend', (hand) => this.release(hand, 'squeeze'));
72	
73	    tools.register({
74	      id: 'ball',
75	      label: 'ボール',
76	      hint: 'つまむ/トリガーで出し、離して投げる',
77	      onSelectStart: (hand) => this.spawnInHand('ball', hand),
78	    });
79	    tools.register({
80	      id: 'block',
81	      label: 'ブロック',
82	      hint: '出して積む。両手でつかむと拡大・回転',
83	      onSelectStart: (hand) => this.spawnInHand('block', hand),
84	    });
85	    app.onClear(() => this.clear());
86	    app.physics.onCollisionStart((c1, c2) => this.handleCollision(c1, c2));
87	  }
88	
89	  get count(): number {
90	    return this.toys.length;
91	  }
92	
93	  end(): void {
94	    this.clear();
95	  }
96	
97	  clear(): void {
98	    while (this.toys.length > 0) this.remove(this.toys[0]);
99	  }
100	
101	  update(ctx: FrameContext): void {
102	    this.time = ctx.time;
103	    for (let i = this.toys.length - 1; i >= 0; i--) {
104	      const toy = this.toys[i];
105	      if (toy.holders.length > 0) {
106	        this.followHands(toy);
107	      } else {
108	        const position = toy.body.translation();
109	        if (position.y < -10) {
110	          // 当たり判定の無い所から落ちていった物は片付ける。
111	          this.remove(toy);
112	          continue;
113	        }
114	        toy.mesh.position.set(position.x, position.y, position.z);
115	        const rotation = toy.body.rotation();
116	        toy.mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
117	      }
118	    }
119	  }
120	
121	  private spawnInHand(kind: ToyKind, hand: HandState): void {
122	    if (!hand.tracked || this.held.has(hand)) return;
123	    if (this.toys.length >= MAX_TOYS) {
124	      const oldest = this.toys.find((toy) => toy.holders.length === 0);
125	      if (oldest) this.remove(oldest);
126	    }
127	    const world = this.app.physics.world;
128	    const material = new THREE.MeshStandardMaterial({
129	      color: new THREE.Color().setHSL(Math.random(), 0.75, 0.55),
130	      roughness: kind === 'ball' ? 0.35 : 0.7,
131	    });
132	    const mesh = new THREE.Mesh(kind === 'ball' ? BALL_GEOMETRY : BLOCK_GEOMETRY, material);
133	    mesh.castShadow = true;
134	    mesh.position.copy(hand.grabPosition);
135	    mesh.quaternion.copy(hand.grabQuaternion);
136	    this.app.scene.add(mesh);
137	
138	    const body = world.createRigidBody(
139	      RAPIER.RigidBodyDesc.dynamic()
140	        .setTranslation(mesh.position.x, mesh.position.y, mesh.position.z)
141	        .setRotation(mesh.quaternion)
142	        // 投げた球が薄い壁をすり抜けないよう、連続衝突判定を使う。
143	        .setCcdEnabled(true)
144	        .setLinearDamping(0.05)
145	        .setAngularDamping(0.4),
146	    );
147	    const toy: Toy = {
148	      kind,
149	      mesh,
150	      body,
151	      collider: world.createCollider(colliderDesc(kind, 1), body),
152	      scale: 1,
153	      holders: [],
154	      offsetPosition: new THREE.Vector3(),
155	      offsetQuaternion: new THREE.Quaternion(),
156	      twoHand: null,
157	      lastImpactTime: 0,
158	    };
159	    this.byCollider.set(toy.collider.handle, toy);
160	    this.toys.push(toy);
161	    this.grab(toy, hand, 'select');
162	  }
163	
164	  private tryGrab(hand: HandState, button: GrabButton): boolean {
165	    if (!hand.tracked || this.held.has(hand)) return false;
166	    let nearest: Toy | null = null;
167	    let nearestDistance = Infinity;
168	    for (const toy of this.toys) {
169	      // ブロックは角までの距離を見込んで広めに取る。
170	      const reach = BASE_SIZE * toy.scale * (toy.kind === 'ball' ? 1 : 1.5) + GRAB_MARGIN;
171	      const distance = toy.mesh.position.distanceTo(hand.grabPosition) - reach;
172	      if (distance < 0 && distance < nearestDistance) {
173	        nearest = toy;
174	        nearestDistance = distance;
175	      }
176	    }
177	    if (!nearest) return false;
178	    this.grab(nearest, hand, button);
179	    return true;
180	  }
181	
182	  private grab(toy: Toy, hand: HandState, button: GrabButton): void {
183	    if (toy.holders.length >= 2) return;
184	    if (toy.holders.length === 0) {
185	      // 持っている間は手に追従させるだけなので、物理の力を受けない kinematic にする。
186	      toy.body.setBodyType(RAPIER.RigidBodyType.KinematicPositionBased, true);
187	    }
188	    toy.holders.push(hand);
189	    this.held.set(hand, { toy, button });
190	    this.beginHold(toy);
191	    hand.pulse(0.5, 25);
192	  }
193	
194	  private release(hand: HandState, button: GrabButton): void {
195	    const holding = this.held.get(hand);
196	    if (!holding || holding.button !== button) return;
197	    this.held.delete(hand);
198	    const toy = holding.toy;
199	    toy.holders.splice(toy.holders.indexOf(hand), 1);
200	    if (toy.twoHand) this.rebuildCollider(toy);
201	
202	    if (toy.holders.length > 0) {
203	      this.beginHold(toy);
204	      return;
205	    }
206	    // 手を離した瞬間の手の速度を、そのまま物の初速にする。
207	    toy.body.setBodyType(RAPIER.RigidBodyType.Dynamic, true);
208	    toy.body.setTranslation(toy.mesh.position, true);
209	    toy.body.setRotation(toy.mesh.quaternion, true);
210	    toy.body.setLinvel(hand.velocity, true);
211	    toy.body.setAngvel({ x: 0, y: 0, z: 0 }, true);
212	    hand.pulse(0.25, 20);
213	  }
214	
215	  /** 持ち手の数が変わったときに、その時点の位置関係を基準として覚え直す。 */
216	  private beginHold(toy: Toy): void {
217	    const [first, second] = toy.holders;
218	    if (second) {
219	      const direction = _a.copy(second.grabPosition).sub(first.grabPosition);
220	      const distance = Math.max(direction.length(), 0.02);
221	      const middle = new THREE.Vector3().addVectors(first.grabPosition, second.grabPosition).multiplyScalar(0.5);
222	      toy.twoHand = {
223	        middle,
224	        direction: direction.clone().normalize(),
225	        distance,
226	        scale: toy.scale,
227	        relativePosition: toy.mesh.position.clone().sub(middle),
228	        quaternion: toy.mesh.quaternion.clone(),
229	      };
230	    } else {
231	      toy.twoHand = null;
232	      _delta.copy(first.grabQuaternion).invert();
233	      toy.offsetPosition.copy(toy.mesh.position).sub(first.grabPosition).applyQuaternion(_delta);
234	      toy.offsetQuaternion.copy(_delta).multiply(toy.mesh.quaternion);
235	    }
236	  }
237	
238	  private followHands(toy: Toy): void {
239	    const [first, second] = toy.holders;
240	    const mesh = toy.mesh;
241	    if (second && toy.twoHand) {
242	      const start = toy.twoHand;
243	      const direction = _a.copy(second.grabPosition).sub(first.grabPosition);
244	      const distance = Math.max(direction.length(), 0.02);
245	      direction.normalize();
246	      toy.scale = THREE.MathUtils.clamp((start.scale * distance) / start.distance, MIN_SCALE, MAX_SCALE);
247	      // 両手を結ぶ線の向きの変化を、そのまま物の回転にする。
248	      _delta.setFromUnitVectors(start.direction, direction);
249	      mesh.quaternion.copy(_delta).multiply(start.quaternion);
250	      mesh.position
251	        .copy(start.relativePosition)
252	        .applyQuaternion(_delta)
253	        .multiplyScalar(toy.scale / start.scale)
254	        .add(_b.addVectors(first.grabPosition, second.grabPosition).multiplyScalar(0.5));
255	      mesh.scale.setScalar(toy.scale);
256	    } else {
257	      mesh.quaternion.copy(first.grabQuaternion).multiply(toy.offsetQuaternion);
258	      mesh.position.copy(toy.offsetPosition).applyQuaternion(first.grabQuaternion).add(first.grabPosition);
259	    }
260	    toy.body.setNextKinematicTranslation(mesh.position);
261	    toy.body.setNextKinematicRotation(mesh.quaternion);
262	  }
263	
264	  /** Rapier のコライダーは後から拡大できないので、大きさが変わったら作り直す。 */
265	  private rebuildCollider(toy: Toy): void {
266	    const world = this.app.physics.world;
267	    this.byCollider.delete(toy.collider.handle);
268	    world.removeCollider(toy.collider, false);
269	    toy.collider = world.createCollider(colliderDesc(toy.kind, toy.scale), toy.body);
270	    this.byCollider.set(toy.collider.handle, toy);
271	  }
272	
273	  private remove(toy: Toy): void {
274	    for (const hand of toy.holders) this.held.delete(hand);
275	    this.byCollider.delete(toy.collider.handle);
276	    // 剛体を消すと、付いているコライダーも一緒に消える。
277	    this.app.physics.world.removeRigidBody(toy.body);
278	    this.app.scene.remove(toy.mesh);
279	    toy.mesh.material.dispose();
280	    this.toys.splice(this.toys.indexOf(toy), 1);
281	  }
282	
283	  private handleCollision(collider1: number, collider2: number): void {
284	    for (const toy of [this.byCollider.get(collider1), this.byCollider.get(collider2)]) {
285	      if (!toy || toy.holders.length > 0) continue;
286	      if (this.time - toy.lastImpactTime < MIN_IMPACT_INTERVAL) continue;
287	      const velocity = toy.body.linvel();
288	      const speed = Math.hypot(velocity.x, velocity.y, velocity.z);
289	      if (speed < MIN_IMPACT_SPEED) continue;
290	      toy.lastImpactTime = this.time;
291	      const position = toy.body.translation();
292	      this.onImpact?.(_a.set(position.x, position.y, position.z), speed, toy.kind);
293	      // 2 つの物どうしの衝突でも、音は 1 回でよい。
294	      return;
295	    }
296	  }
297	}
298	
299	function colliderDesc(kind: ToyKind, scale: number): RAPIER.ColliderDesc {
300	  const size = BASE_SIZE * scale;
301	  const desc = kind === 'ball' ? RAPIER.ColliderDesc.ball(size) : RAPIER.ColliderDesc.cuboid(size, size, size);
302	  return desc
303	    .setDensity(kind === 'ball' ? 300 : 500)
304	    .setRestitution(kind === 'ball' ? 0.75 : 0.15)
305	    .setFriction(kind === 'ball' ? 0.5 : 0.9)
306	    .setActiveEvents(RAPIER.ActiveEvents.COLLISION_EVENTS);
307	}
