1	import * as THREE from 'three';
2	import type { Feature, FrameContext } from './app';
3	
4	export type Handedness = 'left' | 'right';
5	export type InputEvent = 'selectstart' | 'selectend' | 'squeezestart' | 'squeezeend';
6	type Listener = (hand: HandState) => void;
7	
8	/** 速度の計算に使う、直近の位置の記録期間 (秒) */
9	const VELOCITY_WINDOW = 0.1;
10	
11	/**
12	 * 片手ぶんの入力状態。素手 (ハンドトラッキング) とコントローラーの違いを吸収する。
13	 * 座標はすべて local-floor 参照空間 (= ワールド座標)。
14	 */
15	export class HandState {
16	  source: XRInputSource | null = null;
17	  /** このフレームで姿勢が取れたか */
18	  tracked = false;
19	  /** 素手なら true、コントローラーなら false */
20	  isHand = false;
21	  /** 素手: つまんでいる / コントローラー: トリガーを引いている */
22	  selecting = false;
23	  /** コントローラーのグリップボタンを握っている (素手では発生しない) */
24	  squeezing = false;
25	
26	  /** 指し示すレイ (targetRaySpace) */
27	  readonly rayOrigin = new THREE.Vector3();
28	  readonly rayDirection = new THREE.Vector3(0, 0, -1);
29	  readonly rayQuaternion = new THREE.Quaternion();
30	  /** 物をつかむ位置。素手: 親指と人差し指の先の中点 / コントローラー: gripSpace */
31	  readonly grabPosition = new THREE.Vector3();
32	  /** つかんだ物の向きの基準。素手: 手首 / コントローラー: gripSpace */
33	  readonly grabQuaternion = new THREE.Quaternion();
34	  /** ボタンを押す・線を描く先端。素手: 人差し指の先 / コントローラー: レイの原点 */
35	  readonly tipPosition = new THREE.Vector3();
36	  /** 手のひらが向いている方向 (手のひらから外へ出る向き) */
37	  readonly palmNormal = new THREE.Vector3(0, -1, 0);
38	  /** grabPosition の速度 (m/s)。投げるときに使う。 */
39	  readonly velocity = new THREE.Vector3();
40	
41	  private readonly history: { time: number; position: THREE.Vector3 }[] = [];
42	
43	  constructor(readonly handedness: Handedness) {}
44	
45	  /** コントローラーを振動させる。素手や非対応の場合は何もしない。 */
46	  pulse(intensity: number, durationMs: number): void {
47	    const actuator = this.source?.gamepad?.hapticActuators?.[0] as
48	      | { pulse?: (value: number, duration: number) => Promise<boolean> }
49	      | undefined;
50	    void actuator?.pulse?.(intensity, durationMs)?.catch(() => {});
51	  }
52	
53	  /** @internal */
54	  updatePose(ctx: FrameContext): void {
55	    const { frame, refSpace } = ctx;
56	    const source = this.source;
57	    this.tracked = false;
58	    if (!source) return;
59	
60	    const rayPose = frame.getPose(source.targetRaySpace, refSpace);
61	    if (!rayPose) return;
62	    copyPosition(this.rayOrigin, rayPose.transform.position);
63	    copyQuaternion(this.rayQuaternion, rayPose.transform.orientation);
64	    this.rayDirection.set(0, 0, -1).applyQuaternion(this.rayQuaternion);
65	
66	    this.isHand = Boolean(source.hand);
67	    if (source.hand) {
68	      // XRHand は関節名 → XRJointSpace の Map。関節ごとに姿勢と半径が取れる。
69	      const indexTip = getJointPose(frame, source.hand, 'index-finger-tip', refSpace);
70	      const thumbTip = getJointPose(frame, source.hand, 'thumb-tip', refSpace);
71	      const wrist = getJointPose(frame, source.hand, 'wrist', refSpace);
72	      if (!indexTip || !thumbTip || !wrist) return;
73	      copyPosition(this.tipPosition, indexTip.transform.position);
74	      copyPosition(this.grabPosition, thumbTip.transform.position).add(this.tipPosition).multiplyScalar(0.5);
75	      copyQuaternion(this.grabQuaternion, wrist.transform.orientation);
76	      // 手の関節の空間は、-Y が手のひらから外へ出る向きと決められている。
77	      this.palmNormal.set(0, -1, 0).applyQuaternion(this.grabQuaternion);
78	    } else {
79	      const gripPose = source.gripSpace ? frame.getPose(source.gripSpace, refSpace) : null;
80	      const transform = (gripPose ?? rayPose).transform;
81	      copyPosition(this.grabPosition, transform.position);
82	      copyQuaternion(this.grabQuaternion, transform.orientation);
83	      this.tipPosition.copy(this.rayOrigin);
84	      // gripSpace は X 軸が手のひらに垂直。握ったとき、左手のひらは +X、右手のひらは -X を向く。
85	      this.palmNormal.set(this.handedness === 'left' ? 1 : -1, 0, 0).applyQuaternion(this.grabQuaternion);
86	    }
87	    this.tracked = true;
88	    this.updateVelocity(ctx.time);
89	  }
90	
91	  /** @internal */
92	  reset(): void {
93	    this.source = null;
94	    this.tracked = false;
95	    this.selecting = false;
96	    this.squeezing = false;
97	    this.history.length = 0;
98	    this.velocity.set(0, 0, 0);
99	  }
100	
101	  private updateVelocity(time: number): void {
102	    const history = this.history;
103	    history.push({ time, position: this.grabPosition.clone() });
104	    while (history.length > 2 && time - history[0].time > VELOCITY_WINDOW) history.shift();
105	    const oldest = history[0];
106	    const elapsed = time - oldest.time;
107	    if (elapsed > 1e-4) {
108	      this.velocity.copy(this.grabPosition).sub(oldest.position).divideScalar(elapsed);
109	    }
110	  }
111	}
112	
113	/**
114	 * XRSession の inputSources とイベントを、左右の HandState にまとめる。
115	 * three.js の getController() を使わず XRInputSource を直接読んでいるのは、
116	 * WebXR の入力 API がどういう形をしているかをコード上で追えるようにするため。
117	 */
118	export class Input implements Feature {
119	  readonly name = 'input';
120	  readonly left = new HandState('left');
121	  readonly right = new HandState('right');
122	  readonly hands: readonly HandState[] = [this.left, this.right];
123	
124	  private readonly listeners: Record<InputEvent, Listener[]> = {
125	    selectstart: [],
126	    selectend: [],
127	    squeezestart: [],
128	    squeezeend: [],
129	  };
130	  private session: XRSession | null = null;
131	
132	  on(event: InputEvent, listener: Listener): void {
133	    this.listeners[event].push(listener);
134	  }
135	
136	  /** もう一方の手 */
137	  other(hand: HandState): HandState {
138	    return hand === this.left ? this.right : this.left;
139	  }
140	
141	  start(session: XRSession): void {
142	    this.session = session;
143	    session.addEventListener('selectstart', this.handleSelectStart);
144	    session.addEventListener('selectend', this.handleSelectEnd);
145	    session.addEventListener('squeezestart', this.handleSqueezeStart);
146	    session.addEventListener('squeezeend', this.handleSqueezeEnd);
147	  }
148	
149	  end(): void {
150	    const session = this.session;
151	    if (session) {
152	      session.removeEventListener('selectstart', this.handleSelectStart);
153	      session.removeEventListener('selectend', this.handleSelectEnd);
154	      session.removeEventListener('squeezestart', this.handleSqueezeStart);
155	      session.removeEventListener('squeezeend', this.handleSqueezeEnd);
156	    }
157	    this.session = null;
158	    for (const hand of this.hands) hand.reset();
159	  }
160	
161	  update(ctx: FrameContext): void {
162	    for (const hand of this.hands) {
163	      // 素手とコントローラーを持ち替えると、同じ handedness の別の XRInputSource に入れ替わる。
164	      let current: XRInputSource | null = null;
165	      for (const source of ctx.session.inputSources) {
166	        if (source.handedness === hand.handedness) current = source;
167	      }
168	      if (current !== hand.source) {
169	        // 入れ替わりで selectend が届かないことがあるので、押しっぱなしを残さない。
170	        if (hand.selecting) this.setSelecting(hand, false);
171	        if (hand.squeezing) this.setSqueezing(hand, false);
172	        hand.reset();
173	        hand.source = current;
174	      }
175	      hand.updatePose(ctx);
176	    }
177	  }
178	
179	  private handFor(event: XRInputSourceEvent): HandState | null {
180	    const handedness = event.inputSource.handedness;
181	    if (handedness !== 'left' && handedness !== 'right') return null;
182	    const hand = handedness === 'left' ? this.left : this.right;
183	    // update より先にイベントが来ることがあるので、ここでも source を合わせておく。
184	    hand.source ??= event.inputSource;
185	    return hand;
186	  }
187	
188	  private setSelecting(hand: HandState, selecting: boolean): void {
189	    if (hand.selecting === selecting) return;
190	    hand.selecting = selecting;
191	    this.emit(selecting ? 'selectstart' : 'selectend', hand);
192	  }
193	
194	  private setSqueezing(hand: HandState, squeezing: boolean): void {
195	    if (hand.squeezing === squeezing) return;
196	    hand.squeezing = squeezing;
197	    this.emit(squeezing ? 'squeezestart' : 'squeezeend', hand);
198	  }
199	
200	  private emit(event: InputEvent, hand: HandState): void {
201	    for (const listener of this.listeners[event]) {
202	      try {
203	        listener(hand);
204	      } catch (error) {
205	        console.error(`[input] ${event} の処理に失敗しました`, error);
206	      }
207	    }
208	  }
209	
210	  private readonly handleSelectStart = (event: XRInputSourceEvent): void => {
211	    const hand = this.handFor(event);
212	    if (hand) this.setSelecting(hand, true);
213	  };
214	
215	  private readonly handleSelectEnd = (event: XRInputSourceEvent): void => {
216	    const hand = this.handFor(event);
217	    if (hand) this.setSelecting(hand, false);
218	  };
219	
220	  private readonly handleSqueezeStart = (event: XRInputSourceEvent): void => {
221	    const hand = this.handFor(event);
222	    if (hand) this.setSqueezing(hand, true);
223	  };
224	
225	  private readonly handleSqueezeEnd = (event: XRInputSourceEvent): void => {
226	    const hand = this.handFor(event);
227	    if (hand) this.setSqueezing(hand, false);
228	  };
229	}
230	
231	export function getJointPose(
232	  frame: XRFrame,
233	  hand: XRHand,
234	  joint: XRHandJoint,
235	  refSpace: XRReferenceSpace,
236	): XRJointPose | undefined {
237	  const space = hand.get(joint);
238	  return space ? frame.getJointPose?.(space, refSpace) : undefined;
239	}
240	
241	export function copyPosition(target: THREE.Vector3, source: DOMPointReadOnly): THREE.Vector3 {
242	  return target.set(source.x, source.y, source.z);
243	}
244	
245	export function copyQuaternion(target: THREE.Quaternion, source: DOMPointReadOnly): THREE.Quaternion {
246	  return target.set(source.x, source.y, source.z, source.w);
247	}
