1	import type { HandState, Input } from './input';
2	
3	/** メニューで切り替える「道具」。つまみ / トリガーで何が起きるかを決める。 */
4	export interface Tool {
5	  id: string;
6	  label: string;
7	  /** メニューに出す 1 行の操作説明 */
8	  hint: string;
9	  onSelectStart(hand: HandState): void;
10	  onSelectEnd?(hand: HandState): void;
11	}
12	
13	/** select を道具より先に横取りする処理。処理したら true を返す。 */
14	export type Interceptor = (hand: HandState) => boolean;
15	
16	/**
17	 * select (つまみ / トリガー) の行き先を決める。
18	 * 登録順に interceptor を試し (メニューを押す、近くの物をつかむ)、
19	 * 誰も処理しなければ選択中の道具に渡す。
20	 */
21	export class Tools {
22	  readonly list: Tool[] = [];
23	  active: Tool | null = null;
24	  onChange: (() => void) | null = null;
25	
26	  private readonly interceptors: Interceptor[] = [];
27	  /** selectstart を受けた道具。途中で道具を切り替えても selectend を同じ道具に返す。 */
28	  private readonly started = new Map<HandState, Tool>();
29	
30	  constructor(input: Input) {
31	    input.on('selectstart', (hand) => {
32	      if (this.interceptors.some((intercept) => intercept(hand))) return;
33	      const tool = this.active;
34	      if (!tool) return;
35	      this.started.set(hand, tool);
36	      tool.onSelectStart(hand);
37	    });
38	    input.on('selectend', (hand) => {
39	      const tool = this.started.get(hand);
40	      this.started.delete(hand);
41	      tool?.onSelectEnd?.(hand);
42	    });
43	  }
44	
45	  register(tool: Tool): void {
46	    this.list.push(tool);
47	    this.active ??= tool;
48	    this.onChange?.();
49	  }
50	
51	  addInterceptor(interceptor: Interceptor): void {
52	    this.interceptors.push(interceptor);
53	  }
54	
55	  setActive(tool: Tool): void {
56	    this.active = tool;
57	    this.onChange?.();
58	  }
59	}
