  stroke.mesh.geometry.dispose();
  stroke.mesh.geometry = new THREE.TubeGeometry(
    new THREE.CatmullRomCurve3(stroke.points),
    stroke.points.length * 2,
    RADIUS,
    6,
    false,
  );
}

