    app.tools.register({
      id: 'draw',
      label: 'お絵描き',
      hint: 'つまむ/トリガーを引いたまま動かして描く',
      overridesHold: true,
      onSelectStart: (hand) => this.begin(hand),
      onSelectEnd: (hand) => this.finish(hand),
    });
    app.onClear(() => this.clear());
  }

  get count(): number {
    return this.strokes.length;
  }

  end(): void {
    this.clear();
